    async def create_public_routing_priority(
        self, service_name: str, body: models.CreatePublicRoutingPriorityRequest
    ) -> models.VrackTask:
        """create_public_routing_priority calls POST /v1/vrack/{serviceName}/publicRoutingPriority: Create a priority

        This endpoint will create a new 'custom' routing priority.

        You can create a new 'custom' routing priority if you have an additional IP block in your
        vRack in the same region or not.

        You do not have to create a 'custom' routing priority for RTvRack 3AZ to work. If you add an
        additional IP block in a 3AZ region without any routing priority and any additional IP
        block, a 'default' routing priority will automatically be chosen for you.

        Priorities must be set to `1`, `2` or `3` for each availability zone.

        `1` stands for the availability zone with highest priority, which will handle traffic by
        default.

        `2` is the availability zone with second-highest priority, which will handle traffic as soon
        as priority `1` availability zone is not available.

        `3` is the availability zone with lowest priority, it will handle traffic if neither the
        availability zone with priority `1` nor the availability zone with priority `2` are
        available.

        All availability zones in a 3AZ region must be set in the payload in order for the 'custom'
        routing priority to be created.

        Args:
            service_name: The internal name of your vrack
            body: the request body

        Requires the IAM action vrack:apiovh:publicRoutingPriority/create.
        """
        return await self._call(
            _r.OP_CREATE_PUBLIC_ROUTING_PRIORITY,
            path_params={
                "serviceName": service_name,
            },
            body=body,
            body_type=models.CreatePublicRoutingPriorityRequest,
            result=models.VrackTask,
        )

